int army::FlyTo(int destIndex, unsigned char restore_facing)
{
    if (destIndex >= 0 && destIndex < 187) {
        int oldFacing = facing;
        remove_aura();
        remove_binding();
        Fly(destIndex);
        add_aura();
        if (facing != oldFacing && restore_facing)
            Turn(1);
        PlayAnimation(2, 1, 0);
        check_obstacle_attacks(0);
        gpCombatManager->RaiseDoor();
    }
    return 0;
}

